commands:
set -euo pipefail
echo RUN
date -u
echo API_KEY_FILE
if [ -f /etc/ragin/api.key ]; then
  echo FILE=/etc/ragin/api.key
  echo SIZE_BYTES=$(stat -c %s /etc/ragin/api.key 2>/dev/null || echo stat_failed)
  echo HASH_SHA256=$(sha256sum /etc/ragin/api.key 2>/dev/null | cut -d' ' -f1 || echo hash_failed)
  echo CONTENT_LEN=$(wc -c < /etc/ragin/api.key 2>/dev/null || echo wc_failed)
  echo CONTENT_HEAD_HEX=$(head -c 16 /etc/ragin/api.key 2>/dev/null | od -An -tx1 | tr -d ' \n' || echo head_failed)
  echo CONTENT_TAIL_HEX=$(tail -c 16 /etc/ragin/api.key 2>/dev/null | od -An -tx1 | tr -d ' \n' || echo tail_failed)
else
  echo FILE_MISSING=/etc/ragin/api.key
fi
echo DONE
